+    <title>Cat FAQ</title>
+    <style>
+      :root {
+        color-scheme: light;
+        --bg: #f4f7fb;
+        --panel: rgba(255, 255, 255, 0.88);
+        --panel-border: rgba(17, 24, 39, 0.08);
+        --text: #102033;
+        --muted: #54657a;
+        --accent: #ff7a59;
+        --accent-soft: #fff0eb;
+        --shadow: 0 18px 50px rgba(16, 32, 51, 0.12);
