    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --panel: rgba(255, 255, 255, 0.88);
        --panel-border: rgba(17, 24, 39, 0.08);
        --text: #102033;
        --muted: #54657a;
        --accent: #ff7a59;
        --accent-soft: #fff0eb;
        --shadow: 0 18px 50px rgba(16, 32, 51, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #ffffff 0, transparent 35%),
          linear-gradient(180deg, #eef3f9 0%, var(--bg) 100%);
        min-height: 100vh;
      }

      .page {
        width: min(900px, calc(100% - 32px));
        margin: 0 auto;
        padding: 64px 0 80px;
      }

      .hero {
        margin-bottom: 28px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: #a33d23;
        font-size: 0.9rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 18px 0 10px;
        font-size: clamp(2.2rem, 4vw, 4rem);
        line-height: 1.05;
      }

      .lead {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.08rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 16px;
      }

      .example {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
        overflow: hidden;
      }

      .trigger {
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 22px 24px;
        border: 0;
        background: transparent;
        color: inherit;
        text-align: left;
        font: inherit;
        cursor: pointer;
      }

      .trigger:focus-visible {
        outline: 3px solid rgba(255, 122, 89, 0.35);
        outline-offset: -3px;
      }

      .trigger span {
        font-size: 1.08rem;
        font-weight: 700;
        line-height: 1.4;
      }

      .icon {
        flex: 0 0 auto;
        width: 40px;
        height: 40px;
        border-radius: 50%;
        display: grid;
        place-items: center;
        background: #eef3f8;
        color: var(--accent);
        font-size: 1.25rem;
        transition: transform 0.2s ease, background 0.2s ease;
      }

      .example[data-open="true"] .icon {
        transform: rotate(45deg);
        background: var(--accent-soft);
      }

      .details {
        display: grid;
        grid-template-rows: 0fr;
        transition: grid-template-rows 0.25s ease;
      }

      .example[data-open="true"] .details {
        grid-template-rows: 1fr;
      }

      .details > div {
        overflow: hidden;
      }

      .answer {
        padding: 0 24px 22px;
        margin: 0;
        color: var(--muted);
        line-height: 1.7;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 900px);
          padding: 36px 0 48px;
        }

        .trigger {
          padding: 18px 18px;
        }

        .answer {
          padding: 0 18px 18px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="hero" aria-labelledby="faq-title">
        <div class="eyebrow">Cat FAQ</div>
        <h1 id="faq-title">Everything you wanted to know about cats</h1>
        <p class="lead">
          A quick, friendly guide to cat behavior, care, and the little mysteries that make them
          such great companions.
        </p>
      </section>

      <section class="faq" aria-label="Frequently asked questions about cats">
        <div class="example" data-open="false">
          <button class="trigger" type="button" aria-expanded="false" aria-controls="cat-q1">
            <span>Why do cats purr?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="cat-q1" hidden>
            <div>
              <p class="answer">
                Cats purr for several reasons: contentment, comfort, communication, and sometimes
                self-soothing when they are nervous or recovering.
              </p>
            </div>
          </div>
        </div>

        <div class="example" data-open="false">
          <button class="trigger" type="button" aria-expanded="false" aria-controls="cat-q2">
            <span>How much do cats sleep?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="cat-q2" hidden>
            <div>
              <p class="answer">
                Most cats sleep 12 to 16 hours a day, and some kittens or seniors may sleep even
                more. Short bursts of play are usually followed by long naps.
              </p>
            </div>
          </div>
        </div>

        <div class="example" data-open="false">
          <button class="trigger" type="button" aria-expanded="false" aria-controls="cat-q3">
            <span>Do cats need regular grooming?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="cat-q3" hidden>
            <div>
              <p class="answer">
                Yes. Most cats groom themselves, but brushing helps reduce shedding, prevent mats,
                and strengthen your bond with them.
              </p>
            </div>
          </div>
        </div>

        <div class="example" data-open="false">
          <button class="trigger" type="button" aria-expanded="false" aria-controls="cat-q4">
            <span>Why do cats knead blankets?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="cat-q4" hidden>
            <div>
              <p class="answer">
                Kneading is a comforting behavior that starts in kittenhood. Adult cats often do
                it when they feel relaxed, safe, and affectionate.
              </p>
            </div>
          </div>
        </div>
      </section>
    </main>

    <script>
      const examples = document.querySelectorAll(".example");

      examples.forEach((example) => {
        const button = example.querySelector(".trigger");
        const details = example.querySelector(".details");

        button.addEventListener("click", () => {
          const isOpen = example.getAttribute("data-open") === "true";
          example.setAttribute("data-open", String(!isOpen));
          button.setAttribute("aria-expanded", String(!isOpen));
          details.hidden = isOpen;
        });
      });
    </script>
  </body>
</html>
